class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def variants(x):
            s = str(x)
            res = {x}
            for i in range(len(s)):
                for j in range(i + 1, len(s)):
                    t = list(s)
                    t[i], t[j] = t[j], t[i]
                    res.add(int(''.join(t)))
            return res
        vs = [variants(x) for x in nums]
        n = len(nums)
        return sum(1 for i in range(n) for j in range(i + 1, n) if nums[j] in vs[i])

