class Solution {
    private Set<Integer> variants(int x) {
        String s = String.valueOf(x);
        Set<Integer> res = new HashSet<>();
        res.add(x);
        for (int i = 0; i < s.length(); i++)
            for (int j = i + 1; j < s.length(); j++) {
                char[] t = s.toCharArray();
                char tmp = t[i]; t[i] = t[j]; t[j] = tmp;
                res.add(Integer.parseInt(new String(t)));
            }
        return res;
    }
    public int countPairs(int[] nums) {
        Map<String, List<Integer>> buckets = new HashMap<>();
        for (int x : nums) {
            char[] c = String.valueOf(x).toCharArray();
            Arrays.sort(c);
            buckets.computeIfAbsent(new String(c), k -> new ArrayList<>()).add(x);
        }
        int ans = 0;
        for (List<Integer> g : buckets.values()) {
            List<Set<Integer>> vs = new ArrayList<>();
            for (int x : g) vs.add(variants(x));
            for (int i = 0; i < g.size(); i++)
                for (int j = i + 1; j < g.size(); j++)
                    if (vs.get(i).contains(g.get(j))) ans++;
        }
        return ans;
    }
}

